/**
 * Self-contained HTML with a print stylesheet: no account, no download
service, nothing that stops working if we do. Documents about your own
mother should not be hostage to a vendor's uptime.

 * @summary Print it, or save it, from the phone in their hand
 */
export const RenderFamilyFormParams = zod.object({
  caseFormId: zod.coerce.number(),
});

/**
 * Four things are checked before anything is written, and all four are
Component 1's `requireFamilyAuthorization`: the person holds the right
of final disposition, a director recorded which tier of C.R.S.
15-19-106 that was under, they typed their password rather than merely
holding a forwarded link, and the case is not marked disputed.

What is written is append-only and snapshots the answers as they stood
at the moment of signing. A correction is a second authorization.

On a tier that needs a majority, a second authorizing contact signing
the same document adds their own consent to the authorization already
recorded rather than opening a rival one. Nobody consents on anybody
else's behalf here — see `FamilyAuthorizationInput`.

 * @summary Sign an authorization
 */
export const AuthorizeFamilyFormParams = zod.object({
  caseFormId: zod.coerce.number(),
});

export const authorizeFamilyFormBodyPasswordMax = 200;

export const authorizeFamilyFormBodySignedNameMax = 200;

export const authorizeFamilyFormBodySignedRelationshipMax = 120;

export const AuthorizeFamilyFormBody = zod
  .object({
    password: zod.string().min(1).max(authorizeFamilyFormBodyPasswordMax),
    signedName: zod.string().min(1).max(authorizeFamilyFormBodySignedNameMax),
    signedRelationship: zod
      .string()
      .max(authorizeFamilyFormBodySignedRelationshipMax)
      .nullish(),
  })
  .describe(
    "Deliberately short. Two things a family member cannot do here:\n\nClaim a tier. The standing is the one the funeral home recorded\nagainst this person, from documents, and `family-contacts.ts` says at\nlength why an app that let somebody choose it would be wrong in\nexactly the cases that end up in front of a judge.\n\nConsent on somebody else's behalf. A daughter typing \"my brother\nagreed\" is her assertion, not her brother's consent — which is the\nvery thing the majority rule exists to prevent. Every other\nconsenting person either signs here themselves or is recorded by the\nhome, with the channel it came through.\n",
  );

/**
 * Reading this records that they were shown it, at that moment, in that
version. Recording it on the read is the honest option: the fact worth
keeping is that the words were in front of them, and that becomes true
when the page renders.

 * @summary The home's documents, as this person sees them
 */
export const GetFamilyPoliciesResponseItem = zod.object({
  id: zod.number(),
  kind: zod.enum(["price_disclosure", "privacy", "terms", "other"]),
  title: zod.string(),
  note: zod.string().nullable(),
  versionId: zod.number(),
  version: zod.number(),
  body: zod.string(),
  sourceUploadId: zod.number().nullable(),
  publishedAt: zod.date(),
  shownAt: zod.date().nullable(),
  acknowledgedAt: zod.date().nullable(),
});
export const GetFamilyPoliciesResponse = zod.array(
  GetFamilyPoliciesResponseItem,
);

/**
 * Separate from being shown it, because being shown a privacy notice is
not agreeing to it and collapsing the two records a consent nobody
gave.

 * @summary Confirm they have read it
 */
export const AcknowledgeFamilyPolicyParams = zod.object({
  versionId: zod.coerce.number(),
});

export const acknowledgeFamilyPolicyBodyNameMax = 200;

export const AcknowledgeFamilyPolicyBody = zod.object({
  name: zod
    .string()
    .min(1)
    .max(acknowledgeFamilyPolicyBodyNameMax)
    .describe("Typed by them, kept verbatim."),
});

